import { deflateSync } from "node:zlib";

export const PNG_BYTES = png(1, 1);

export const JPEG_BYTES = new Uint8Array(
  Buffer.from(
    "",
    "base64",
  ),
);

export const WEBP_BYTES = new Uint8Array(Buffer.from("UklGRjIAAABXRUJQVlA4ICYAAABwAQCdASoDAAIAAUAmJZgCdAFAAAD++SplpEIP/4IL+IL+IK/gAA==", "base64"));

export function png(width: number, height: number): Uint8Array {
  const chunk = (type: string, data: Buffer) => {
    const body = Buffer.concat([Buffer.from(type), data]);
    let crc = 0xffffffff;
    for (const byte of body) {
      crc ^= byte;
      for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
    }
    const length = Buffer.alloc(4);
    length.writeUInt32BE(data.length);
    const checksum = Buffer.alloc(4);
    checksum.writeUInt32BE((crc ^ 0xffffffff) >>> 0);
    return Buffer.concat([length, body, checksum]);
  };
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8;
  header[9] = 2;
  return new Uint8Array(
    Buffer.concat([
      Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
      chunk("IHDR", header),
      chunk("IDAT", deflateSync(Buffer.alloc((width * 3 + 1) * height))),
      chunk("IEND", Buffer.alloc(0)),
    ]),
  );
}
